// paginatedReaderAssertPageZeroOnError asserts Page returns the zero for every result alongside any error.
func paginatedReaderAssertPageZeroOnError(
	tb testing.TB,
	p PaginatedReader,
	fx PaginatedReaderFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, got2, err := p.Page(ctx, fx.Cursor())
	if err == nil {
		tb.Skip("Page answered for a cancelled context, so this check has no error to inspect")
	}

	if got != nil {
		tb.Errorf("Page must return nothing for its result 1 alongside an error (err %v)", err)
	}
	var zero2 int
	if got2 != zero2 {
		tb.Errorf("Page must return the zero int alongside an error: got %+v, want %+v (err %v)",
			got2, zero2, err)
	}
}

